import { Field, ObjectType } from '@nestjs/graphql';
import { Prop, Schema } from '@nestjs/mongoose';
import { Types } from 'mongoose';
import { ObjectIdScalar } from 'src/common';
import { COLLECTIONS } from 'src/constants';
import { Category } from 'src/modules/category/schema';
import { User } from 'src/modules/user/schema';
import { OrderStatusEnum, OrderUrgencyEnum } from '../enums';
import { GEO_POINT_SCHEMA, GeoJsonPoint, GeoPoint } from 'src/shared/geo';

/**
 * "Order" = user announcement / buy request.
 *
 * Generated by the "I didn't find what I needed → create request" flow,
 * or by the dedicated CreateOrder screen. Sellers browse the Orders feed
 * and contact the author by phone.
 */
@ObjectType()
@Schema({ timestamps: true })
export class Order {
  @Field(() => ObjectIdScalar)
  _id: Types.ObjectId;

  @Field()
  @Prop({ required: true, index: true })
  title: string;

  @Field()
  @Prop({ default: '' })
  description: string;

  /** Nullable when the user document was removed but the order remains. */
  @Field(() => User, { nullable: true })
  @Prop({
    type: Types.ObjectId,
    ref: COLLECTIONS.USERS,
    required: true,
    index: true,
  })
  author?: User | Types.ObjectId | null;

  @Field()
  @Prop({ required: true })
  phone: string;

  /** Free-form address. */
  @Field({ nullable: true })
  @Prop({ default: '' })
  location?: string;

  /** Region slug, used for "promoted in your region first" sorting. */
  @Field({ nullable: true })
  @Prop({ default: '', index: true })
  region?: string;

  @Field(() => GeoPoint, { nullable: true })
  geoLocation?: GeoPoint | null;

  @Prop({ type: GEO_POINT_SCHEMA, required: false })
  geo?: GeoJsonPoint;

  @Field(() => Category, { nullable: true })
  @Prop({
    type: Types.ObjectId,
    ref: COLLECTIONS.CATEGORIES,
    default: null,
    index: true,
  })
  brand?: Types.ObjectId | Category | null;

  @Field(() => Category, { nullable: true })
  @Prop({
    type: Types.ObjectId,
    ref: COLLECTIONS.CATEGORIES,
    default: null,
    index: true,
  })
  carModel?: Types.ObjectId | Category | null;

  /** Part-category leaf. */
  @Field(() => Category, { nullable: true })
  @Prop({
    type: Types.ObjectId,
    ref: COLLECTIONS.CATEGORIES,
    default: null,
    index: true,
  })
  partCategory?: Types.ObjectId | Category | null;

  @Field({ nullable: true })
  @Prop({ default: 0, min: 0 })
  budget?: number;

  @Field({ nullable: true })
  @Prop({ default: '' })
  currency?: string;

  @Field(() => OrderUrgencyEnum, { nullable: true })
  @Prop({
    type: String,
    enum: Object.values(OrderUrgencyEnum),
    default: OrderUrgencyEnum.MEDIUM,
    index: true,
  })
  urgency?: OrderUrgencyEnum;

  @Field(() => OrderStatusEnum)
  @Prop({
    type: String,
    enum: Object.values(OrderStatusEnum),
    default: OrderStatusEnum.ACTIVE,
    index: true,
  })
  status: OrderStatusEnum;

  @Field(() => [String], { nullable: true })
  @Prop({ type: [String], default: [] })
  images?: string[];

  @Field()
  @Prop({ default: false, index: true })
  isPromoted: boolean;

  @Field(() => Date, { nullable: true })
  @Prop({ type: Date, default: null })
  promotedUntil?: Date | null;

  @Field()
  createdAt: Date;

  @Field({ nullable: true })
  updatedAt?: Date;
}
